<template><div><header class="admin-page-header"><div><h1>用户管理</h1><p>查看账号状态并锁定异常账号。</p></div></header><div class="admin-toolbar"><el-button :loading="loading" @click="load"><RefreshCw :size="17"/>刷新</el-button></div><AdminState v-if="loading" kind="loading" message="正在加载用户…"/><AdminState v-else-if="error" kind="error" :message="error"/><AdminState v-else-if="!users.length" kind="empty" message="暂无用户。"/><el-table v-else :data="users" stripe><el-table-column prop="id" label="ID" width="76"/><el-table-column prop="username" label="用户名" min-width="130"/><el-table-column prop="email" label="邮箱" min-width="220" show-overflow-tooltip/><el-table-column prop="role" label="角色" width="100"/><el-table-column prop="status" label="状态" width="110"><template #default="scope"><span :class="scope.row.status==='ACTIVE'?'status-value':'danger-text'">{{scope.row.status}}</span></template></el-table-column><el-table-column label="操作" width="110" fixed="right"><template #default="scope"><el-button class="danger-text" type="text" :disabled="scope.row.status==='LOCKED'" @click="lock(scope.row)">锁定</el-button></template></el-table-column></el-table></div></template>
<script>import{RefreshCw}from'lucide-vue';import{adminApi}from'../api/index.js';import AdminState from'../components/AdminState.vue';import{adminProblemMessage}from'../ui/admin-model.js';export default{name:'UsersView',components:{AdminState,RefreshCw},data:()=>({loading:true,error:'',users:[]}),async mounted(){await this.load();},methods:{async load(){this.loading=true;this.error='';try{this.users=await adminApi.users();}catch(problem){this.error=adminProblemMessage(problem);}finally{this.loading=false;}},async lock(user){try{await this.$confirm(`确认锁定用户“${user.username}”？`,'锁定用户',{confirmButtonText:'锁定',cancelButtonText:'取消',type:'warning'});await adminApi.lockUser(user.id);await this.load();this.$message.success('用户已锁定。');}catch(problem){if(problem!=='cancel'&&problem!=='close')this.$message.error(adminProblemMessage(problem));}}}};</script>
